-- Split phases 5-6: co-admins, recurring group expenses, weekly payment reminders.
ALTER TABLE split."SplitGroupMembers"
    ADD COLUMN IF NOT EXISTS "IsAdmin" boolean NOT NULL DEFAULT false;

ALTER TABLE split."SplitGroups"
    ADD COLUMN IF NOT EXISTS "AutoRemind" boolean NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS "LastAutoRemindAt" timestamp with time zone NULL;

CREATE TABLE IF NOT EXISTS split."SplitRecurringExpenses" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "SplitGroupId" integer NOT NULL,
    "CreatedByUserId" text NOT NULL,
    "Description" text NOT NULL,
    "Amount" numeric(18,2) NOT NULL,
    "Category" text NULL,
    "SplitType" integer NOT NULL DEFAULT 0,
    "Notes" text NULL,
    "PayersJson" text NOT NULL,
    "ParticipantsJson" text NOT NULL,
    "Frequency" integer NOT NULL DEFAULT 2,
    "StartDate" timestamp with time zone NOT NULL,
    "NextRunDate" timestamp with time zone NOT NULL,
    "EndDate" timestamp with time zone NULL,
    "RunCount" integer NOT NULL DEFAULT 0,
    "IsActive" boolean NOT NULL DEFAULT true,
    "LastRunAt" timestamp with time zone NULL,
    "LastError" text NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UpdatedAt" timestamp with time zone NULL,
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "DeletedAt" timestamp with time zone NULL,
    CONSTRAINT "CK_SplitRecurringExpenses_Amount" CHECK ("Amount" > 0),
    CONSTRAINT "FK_SplitRecurringExpenses_SplitGroups_SplitGroupId" FOREIGN KEY ("SplitGroupId")
        REFERENCES split."SplitGroups" ("Id") ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS "IX_SplitRecurringExpenses_IsActive_NextRunDate" ON split."SplitRecurringExpenses" ("IsActive", "NextRunDate");
CREATE INDEX IF NOT EXISTS "IX_SplitRecurringExpenses_SplitGroupId" ON split."SplitRecurringExpenses" ("SplitGroupId");
